'use strict';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['overview','概览','总览 入门 能力 介绍'],['architecture','架构与数据流','pipeline registry runner 数据 训练'],['quickstart','快速启动','安装 pip conda CLI Python dry-run resolve train 运行'],['configuration','配置实验','YAML SFT DPO RLHF LoRA 模型 数据集'],['extensions','自定义与扩展','注册 register dataset method backend runner 自定义'],['reference','参考与排错','API 文件 测试 pytest 常见问题']];
let catalog,pageName='overview',codeBlocks=new Map(),codeSequence=0,outline=[],extension='runner',sourceText='',sourceName='',toastTimer;
const state={scenario:'sft',backend:'trl',model:'Qwen/Qwen2.5-7B-Instruct'};
const pathTo=page=>`#alignment/${page}`;
function note(text){return `<div class="status-note"><span>↳</span><div>${text}</div></div>`;}
function section(id,title,body){outline.push([id,title]);return `<section id="${id}" class="doc-section"><h2>${title}</h2>${body}</section>`;}
function header(kicker,title,description){return `<header class="page-header"><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${description}</p></header>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function syntax(line){const re=/(#[^\n]*$|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:from|import|class|def|return|for|in|with|as|if|else|print|True|False|None)\b|\b\d+(?:\.\d+)?\b)/g;let out='',previous=0;for(const match of line.matchAll(re)){out+=esc(line.slice(previous,match.index));const token=match[0],type=token.startsWith('#')?'comment':/^['"]/.test(token)?'string':/^\d/.test(token)?'number':'keyword';out+=`<span class="tok-${type}">${esc(token)}</span>`;previous=match.index+token.length;}return out+esc(line.slice(previous));}
function code(text,label='Python',language='python',filename=null,output=false){const id=`code-${codeSequence++}`;codeBlocks.set(id,{text,filename});return `<div class="code-block${output?' output':''}"><div class="code-heading"><span>${esc(label)}</span><div class="code-actions">${filename?`<button data-download="${id}">下载 ↓</button>`:''}<button data-copy="${id}" aria-label="复制 ${esc(label)}">复制 ⧉</button></div></div><pre><code>${text.split('\n').map(line=>`<span class="code-line">${output?esc(line):syntax(line)}</span>`).join('')}</code></pre></div>`;}
function readmeCode(language,index=0){return catalog.alignment.blocks.filter(b=>b.language===language)[index]?.code||'';}
function overview(){
 outline.push(['overview-hero','先配置环境'],['workflow-map','选择工作流'],['capabilities','下一步']);
 return header('START HERE / 01','先配置环境，再开始训练','Alignment Toolkit 的训练依赖 GPU、PyTorch 和 TRL。先完成环境配置，再选择 SFT、DPO 或 RLHF。')+
 section('overview-hero','01 · 配置训练环境',`<div class="status-note"><span>↳</span><div><strong>推荐先执行下面的环境配置。</strong><br>它会创建 Conda 环境、安装 PyTorch CUDA、Transformers、Datasets、Accelerate 和 TRL。</div></div>${code('conda activate alignment-toolkit\nbash scripts/setup_env.sh\npython -m pip check\npython -c "import torch; print(torch.cuda.is_available())"','终端 / 环境配置','bash')}<a class="button primary" href="console.html">环境准备好后，进入训练控制台 <span>↗</span></a>`)+
 section('workflow-map','02 · 选择工作流',`<div class="journey-list"><a class="journey-link" href="console.html"><span class="journey-index">01</span><div><h3>SFT · 指令微调</h3><p>使用 instruction 数据训练初始 policy。</p><code>alignment train · SFTTrainer</code></div><span class="journey-arrow">↗</span></a><a class="journey-link" href="console.html"><span class="journey-index">02</span><div><h3>DPO · 偏好优化</h3><p>使用 chosen / rejected 偏好对直接优化 policy。</p><code>alignment train · DPOTrainer</code></div><span class="journey-arrow">↗</span></a><a class="journey-link" href="console.html"><span class="journey-index">03</span><div><h3>RLHF · 三阶段训练</h3><p>SFT → Reward Model → PPO，阶段 checkpoint 自动传递。</p><code>alignment train · TRLRunner</code></div><span class="journey-arrow">↗</span></a></div>`)+
 section('capabilities','03 · 运行前检查',table(['检查项','你需要确认'],[['GPU','nvidia-smi 能看到目标 GPU，显存足够。'],['模型','本地路径或 Hugging Face ID 可由 from_pretrained 加载。'],['数据','数据集 ID、split 和字段 mapping 正确。'],['输出','output.root 有足够磁盘空间。']]));
}
const architectureNodes=[{title:'YAML 配置',small:'描述实验',status:'已实现',file:'src/alignment_toolkit/config.py',input:'configs/experiments/*.yaml',output:'原始配置字典',detail:'load_experiment() 读取 YAML，解析 models、pipeline、datasets 和 evaluation。'},{title:'Registry',small:'匹配能力',status:'已实现',file:'src/alignment_toolkit/registry.py',input:'method / backend / dataset',output:'方法与数据定义',detail:'检查方法与后端是否注册，后端是否支持该方法，以及 dataset.kind 是否满足方法要求。'},{title:'PipelineSpec',small:'结构化结果',status:'已实现',file:'src/alignment_toolkit/pipeline.py',input:'解析后的配置',output:'StageSpec[] + models + raw',detail:'每个 StageSpec 保留 stage_id、method、backend、dataset、input 和 training。'},{title:'TRLRunner',small:'执行训练',status:'已实现',file:'src/alignment_toolkit/trl_runner.py',input:'PipelineSpec + TRL',output:'阶段 checkpoint / 训练结果',detail:'加载 Hugging Face 数据和模型，调用 SFT、DPO、Reward、PPO Trainer，并传递阶段产物。'}];
function archDetail(index){const node=architectureNodes[index];return `<div class="detail-top"><h3>${node.title} · ${node.small}</h3><span class="tag">${node.status}</span></div><p>${node.detail}</p><div class="io-grid"><div><small>INPUT</small><code>${node.input}</code></div><div><small>OUTPUT</small><code>${node.output}</code></div></div><button class="source-link" data-source="${esc(node.file)}">查看 ${esc(node.file)} ↗</button>`;}
function architecture(){return header('ARCHITECTURE / 01','理解一次实验如何流动','从 YAML 到结构化 pipeline，再交给 TRL runner。点击节点查看每一层的职责与源码入口。')+section('architecture-map','四个关键环节',`<div class="architecture"><div class="arch-nodes">${architectureNodes.map((node,i)=>`<button class="arch-node${i?'':' active'}" data-node="${i}" aria-pressed="${!i}"><span class="node-num">0${i+1}</span><strong>${node.title}</strong><small>${node.small}</small></button>`).join('')}</div><div id="arch-detail" class="arch-detail" aria-live="polite">${archDetail(0)}</div></div>`)+section('architecture-contracts','方法与数据的约定',table(['方法','数据类型','模型角色','默认后端'],catalog.alignment.methods.map(m=>[`<code>${esc(m.name)}</code>`,esc(m.dataset_kinds.join(' / ')),esc(m.model_roles.join(', ')),`<code>${esc(m.default_backend)}</code>`])))+section('architecture-boundaries','解析成功意味着什么',note('解析成功表示已通过当前 registry 与数据类型检查。<strong>train 会进一步加载模型和数据，评测与多机能力仍由 runner 扩展。</strong>'));}
function quickstart(){const install=`cd ${catalog.alignment.root}\n# 需要 Conda 和兼容的 NVIDIA 驱动\nbash scripts/setup_env.sh\nconda activate alignment-toolkit`;return header('QUICK START / 02','先运行一个最小示例','配置解析无需 GPU；实际训练需要安装 TRL 依赖、可用 GPU 和 Hugging Face 访问。')+section('install','01 · 安装当前项目',code(install,'终端 / 安装','bash'))+section('first-run','02 · 解析第一个实验',code('alignment dry-run --config configs/experiments/sft.yaml','终端 / dry-run','bash')+code('dry-run ok: 1 stage(s)','预期输出','text',null,true))+section('train-run','03 · 执行训练',code('alignment train --config configs/experiments/rlhf.yaml','终端 / TRL training','bash')+note('RLHF 配置按 SFT → Reward Model → PPO 运行；DPO 使用独立的 dpo.yaml。'))+section('evaluate-run','04 · 运行安全评估',code("python -m pip install -e '.[eval]'\nalignment evaluate --config configs/experiments/rlhf.yaml \\n  --max-samples 8",'终端 / safety evaluation','bash')+note('当前执行 refusal_heuristic，输出逐样本 JSONL 和 summary.json。'))+section('python-api','05 · 在 Python 中读取实验',code(readmeCode('python'),'Python / 从 README 提取','python','alignment_inspect.py'));}
function yamlScalar(value){return value===null?'null':typeof value==='string'?JSON.stringify(value):String(value);}
function yamlDump(value,indent=0){const pad=' '.repeat(indent);if(Array.isArray(value))return value.map(item=>item&&typeof item==='object'?`${pad}- ${yamlDump(item,indent+2).trimStart()}`:`${pad}- ${yamlScalar(item)}`).join('\n');return Object.entries(value).map(([key,item])=>item&&typeof item==='object'?`${pad}${key}:\n${yamlDump(item,indent+2)}`:`${pad}${key}: ${yamlScalar(item)}`).join('\n');}
function options(values,selected){return values.map(item=>{const [value,label]=Array.isArray(item)?item:[item,item];return `<option value="${esc(value)}"${value===selected?' selected':''}>${esc(label)}</option>`;}).join('');}
function field(name,label,values,help=''){const selected=state[name];return `<div class="field"><label for="config-${name}">${label}</label>${values?`<select id="config-${name}" data-config="${name}">${options(values,selected)}</select>`:`<input id="config-${name}" data-config="${name}" value="${esc(selected)}" maxlength="256" spellcheck="false" required>`}${help?`<p class="field-help">${help}</p>`:''}</div>`;}
function generatedConfig(){const config=structuredClone(catalog.alignment.configs[`configs/experiments/${state.scenario}.yaml`].data);for(const model of Object.values(config.models||{}))model.id=state.model;if(state.scenario!=='rlhf')config.pipeline.stages[0].method.backend=state.backend;config.pipeline.name=`my_${state.scenario}`;return config;}
function configFields(){const backends=state.scenario==='rlhf'?[['trl','TRL']]:catalog.alignment.backends.filter(b=>b.methods.includes(state.scenario)).map(b=>b.name);return field('scenario','实验模板',[['sft','SFT · 指令微调'],['dpo','DPO · 偏好优化'],['rlhf','RLHF · 三阶段']])+field('model','Hugging Face 模型 ID',null)+field('backend','训练后端',backends,'当前默认使用 TRL。');}
function configPreview(){const name=`my_${state.scenario}.yaml`;return code(`${yamlDump(generatedConfig())}\n`,name,'yaml',name);}
function configuration(){return header('CONFIGURATION / 03','把实验写成一份配置','从仓库现有 SFT、DPO、RLHF 示例出发，修改模型与训练参数，复制或下载自己的 YAML。')+section('config-builder','配置生成器',`<div class="config-workbench"><div class="config-form"><h3>配置选项</h3><div id="config-fields">${configFields()}</div><p class="config-help">这里只生成配置文本。下载后请在 toolkit 根目录验证；不会从页面启动训练或修改项目文件。</p></div><div id="config-preview" class="config-preview">${configPreview()}</div></div><p class="preview-caption">保存位置：<code>${esc(catalog.alignment.root)}/</code></p><div id="config-command">${code(`alignment dry-run --config my_${state.scenario}.yaml`,'终端 / 验证下载的配置','bash')}</div>`)+section('config-fields-guide','理解主要字段',table(['字段','用途'],[['models','声明 Hugging Face 模型来源与标识。'],['datasets','在当前 YAML 内声明训练数据源、字段映射和 split。'],['pipeline.stages','声明阶段方法、数据集与输入引用。'],['training','按阶段传递 TRL 训练参数和 LoRA 配置。'],['evaluation','指定评估阶段、外部安全 suites 和输出约定。']]))+section('config-source','查看原始配置',`<p class="body-copy">本页模板直接读取仓库文件。点击文件名查看原文。</p><div class="source-list">${Object.keys(catalog.alignment.configs).filter(x=>x.includes('experiments')||x.endsWith('datasets.yaml')).map(file=>`<button data-source="${esc(file)}">${esc(file)} ↗</button>`).join('')}</div>`);}
const extensionInfo={runner:['扩展 Runner','内置 TRLRunner 已负责 SFT、DPO、Reward Model 和 PPO；扩展时可实现自己的 run(spec) 以替换训练调度。','训练需要 GPU · 需要 .[train]'],dataset:['注册数据集','声明数据类型、adapter 名称和 source，并在 runner 中实现对应加载逻辑。','无需 GPU · 可直接运行'],method:['注册方法与后端','新增方法时，同时声明后端支持的 methods；仅注册方法不会自动生成训练实现。','无需 GPU · 可直接运行']};
function extensionCode(){return extension==='runner'?readmeCode('python',1):catalog.alignment.extensions[extension]||'';}
function extensionPanel(){const item=extensionInfo[extension];return `<p class="extension-description">${item[1]}</p><span class="requirement-label">${item[2]}</span>${code(extensionCode(),`${extension}.py`,'python',`alignment_${extension}.py`)}<p class="body-copy">运行位置：<code class="inline-code">${esc(catalog.alignment.root)}</code>。</p>`;}
function extensions(){return header('EXTENSIONS / 04','从一个明确的接口开始扩展','先理解扩展点负责什么，再运行完整的最小示例。')+section('extension-examples','选择要扩展的部分',`<div class="tabs" role="group" aria-label="扩展类型">${Object.entries(extensionInfo).map(([key,item])=>`<button class="tab${extension===key?' active':''}" data-extension="${key}" aria-pressed="${extension===key}">${item[0]}</button>`).join('')}</div><div id="extension-panel">${extensionPanel()}</div>`)+section('extension-contract','把声明与实际执行接起来',table(['扩展点','你需要补齐的逻辑'],[['DatasetDefinition','数据源到统一样本的转换。adapter 名称只是约定。'],['MethodDefinition / BackendDefinition','方法能力声明，以及后端对应的训练调用。'],['runner.run(spec)','阶段调度、模型加载与产物传递、结果保存、评测集成。']]));}
const faqs=[['找不到 alignment 命令？','确认 python -m pip install -e . 与运行命令使用同一环境。也可使用 python -m alignment_toolkit.cli dry-run --config configs/experiments/sft.yaml。'],['dry-run 成功，为什么没有开始训练？','dry-run 只解析配置。需要实际训练时执行 alignment train，并确保已安装 .[train] 和可用 GPU。'],['LoRA 如何共享 reference base？','在阶段 training 中设置 lora 和 adapter_disabled: true；TRL 会关闭 adapter 计算 reference policy。'],['训练输出在哪里？','默认写入 output.root/<pipeline>/<stage>/；LoRA 默认训练后 merge，Reward Model 会保存 score head。']];
function reference(){return header('REFERENCE / 05','查接口，也查边界','常用 API、输出行为和常见错误集中在这里。')+section('api-reference','常用入口',table(['接口','作用'],[['load_experiment(path)','读取 YAML 并返回 PipelineSpec。'],['resolve_experiment(config)','从 Python 字典解析 pipeline。'],['AlignmentExperiment(spec).dry_run()','返回已有 spec。'],['AlignmentExperiment(spec, runner=TRLRunner()).run()','调用 TRL runner 执行训练。']]))+section('faq','常见问题',faqs.map(([question,answer])=>`<details class="faq"><summary>${question}</summary><p>${esc(answer)}</p></details>`).join(''))+section('tests','验证本地实现',code('python -m pytest -q','终端 / 在 toolkit 根目录运行','bash')+'<p class="body-copy">测试覆盖内置配置、路径解析和 TRL 训练参数处理。</p>')+section('source-files','源码与文档入口',`<div class="source-list">${catalog.alignment.sources.map(file=>`<button data-source="${esc(file)}">${esc(file)} ↗</button>`).join('')}</div>`);}
const renderers={overview,architecture,quickstart,configuration,extensions,reference};
function route(){const nextPage=location.hash.slice(1).split('/')[1];pageName=pages.some(p=>p[0]===nextPage)?nextPage:'overview';$('breadcrumb-toolkit').textContent='Alignment';$('breadcrumb-page').textContent=pages.find(p=>p[0]===pageName)[1];document.title=`Alignment · ${$('breadcrumb-page').textContent} | Toolkit Field Guide`;$('navigation').innerHTML=pages.map(([id,title],index)=>`<a class="nav-link${pageName===id?' active':''}" href="${pathTo(id)}"${pageName===id?' aria-current="page"':''}><span class="nav-index">0${index+1}</span><span>${title}</span>${pageName===id?'<span class="nav-arrow">↗</span>':''}</a>`).join('');codeBlocks=new Map();codeSequence=0;outline=[];const next=pages[(pages.findIndex(p=>p[0]===pageName)+1)%pages.length];$('content').innerHTML=`<div class="fade-in">${renderers[pageName]()}<div class="page-end"><span>内容来自当前 Alignment Toolkit README 与实现</span><a href="${pathTo(next[0])}">${next[1]} →</a></div></div>`;$('page-outline').innerHTML=`<p class="outline-label">本页内容 / ON THIS PAGE</p>${outline.map(([id,title])=>`<button class="outline-link" data-scroll="${id}">${esc(title)}</button>`).join('')}<div class="outline-note">所有命令在 toolkit 根目录运行。<code>alignment_toolkit/</code></div>`;window.scrollTo({top:0,behavior:'instant'});}
function notify(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,2300);}
async function copy(text){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const buffer=document.createElement('textarea');buffer.value=text;buffer.style.position='fixed';buffer.style.left='-9999px';document.body.append(buffer);buffer.select();document.execCommand('copy');buffer.remove();}notify('已复制，可粘贴到终端或编辑器');}catch{notify('浏览器未允许复制，请手动复制');}}
function download(text,filename){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function openSource(file){sourceName=file;$('source-title').textContent=`alignment_toolkit / ${file}`;$('source-content').textContent='正在读取…';$('source-dialog').showModal();try{const response=await fetch(`api/source?file=${encodeURIComponent(file)}`);if(!response.ok)throw Error('读取失败');sourceText=await response.text();$('source-content').textContent=sourceText;}catch{$('source-content').textContent='源文件读取失败，请关闭后重试。';}}
function closeSidebar(){document.body.classList.remove('sidebar-open');$('sidebar-scrim').hidden=true;$('menu-button').setAttribute('aria-expanded','false');}
function renderSearch(){const query=$('search-input').value.toLowerCase().trim();const results=pages.filter(([,title,keywords])=>`alignment 对齐 ${title} ${keywords}`.toLowerCase().includes(query));$('search-results').innerHTML=results.length?results.map(([id,title,keywords])=>`<a class="search-result" href="${pathTo(id)}" data-search-result>Alignment · ${title}<small>${esc(keywords)}</small></a>`).join(''):'<p class="search-empty">没有匹配的主题。试试「配置」「TRL」或「runner」。</p>';}
function openSearch(){$('search-input').value='';renderSearch();$('search-dialog').showModal();$('search-input').focus();}
function updateConfig(event){const target=event.target;if(!target.dataset.config||(event.type==='input'&&target.tagName==='SELECT')||(event.type==='change'&&target.tagName==='INPUT'))return;state[target.dataset.config]=target.value;if(target.dataset.config==='scenario')state.backend='trl';$('config-fields').innerHTML=configFields();$('config-preview').innerHTML=configPreview();}
$('menu-button').addEventListener('click',()=>{const open=!document.body.classList.contains('sidebar-open');document.body.classList.toggle('sidebar-open',open);$('sidebar-scrim').hidden=!open;$('menu-button').setAttribute('aria-expanded',String(open));});$('sidebar-scrim').addEventListener('click',closeSidebar);$('footer-source').addEventListener('click',()=>openSource('README.md'));$('source-copy').addEventListener('click',()=>copy(sourceText));$('source-download').addEventListener('click',()=>download(sourceText,sourceName.split('/').at(-1)));$('open-search').addEventListener('click',openSearch);$('search-input').addEventListener('input',renderSearch);document.addEventListener('input',updateConfig);document.addEventListener('change',updateConfig);document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(!$('search-dialog').open)openSearch();}if(event.key==='Escape')closeSidebar();});document.addEventListener('click',event=>{const target=event.target.closest('button,a');if(!target)return;if(target.dataset.copy){const item=codeBlocks.get(target.dataset.copy);if(item)copy(item.text);return;}if(target.dataset.download){const item=codeBlocks.get(target.dataset.download);if(item)download(item.text,item.filename);return;}if(target.dataset.source){openSource(target.dataset.source);return;}if(target.dataset.scroll){$(target.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}if(target.dataset.closeDialog){$(target.dataset.closeDialog).close();return;}if(target.hasAttribute('data-search-result')){$('search-dialog').close();return;}if(target.hasAttribute('data-node')){document.querySelectorAll('[data-node]').forEach(node=>{node.classList.toggle('active',node===target);node.setAttribute('aria-pressed',String(node===target));});$('arch-detail').innerHTML=archDetail(Number(target.dataset.node));return;}if(target.dataset.extension){extension=target.dataset.extension;document.querySelectorAll('[data-extension]').forEach(node=>{node.classList.toggle('active',node===target);node.setAttribute('aria-pressed',String(node===target));});$('extension-panel').innerHTML=extensionPanel();}});window.addEventListener('hashchange',route);
async function load(){try{const response=await fetch('api/docs');if(!response.ok)throw Error('读取失败');catalog=await response.json();route();}catch{$('content').innerHTML='<div class="loading"><h1>暂时无法读取文档</h1><p>请确认 Alignment 文档服务正常运行后重试。</p></div>';}}
load();
